// The same structure both ways, so the indentation stops being mysterious.
const asObject = {
  name: "ci",
  on: { push: { branches: ["main"] } },
  jobs: { smoke: { "runs-on": "ubuntu-latest", steps: [{ run: "npm ci" }] } },
};

console.log(JSON.stringify(asObject, null, 2));
console.log("\n--- the YAML for exactly that ---");
console.log(`name: ci
on:
  push:
    branches: [main]
jobs:
  smoke:
    runs-on: ubuntu-latest
    steps:
      - run: npm ci`);

import { REPO_ROOT } from "../_shared/deno-helpers.ts";

// AUTHORED, NOT EXECUTED - Jenkins is not installed here.

const jenkinsfile = await Deno.readTextFile(`${REPO_ROOT}/week6/generated/day5-Jenkinsfile`);
console.log(jenkinsfile);

import { REPO_ROOT } from "../_shared/deno-helpers.ts";

// A real workflow. NOT installed - it lives in week6/generated/ on purpose.

const workflowYaml = await Deno.readTextFile(`${REPO_ROOT}/week6/generated/day5-github-actions.yml`);
console.log(workflowYaml);

// The cheapest CI habit there is: check the file before you push it.
import { REPO_ROOT as ROOT2 } from "../_shared/deno-helpers.ts";

const wf = await Deno.readTextFile(`${ROOT2}/week6/generated/day5-github-actions.yml`);
const wfLines = wf.split(String.fromCharCode(10));

// 1. Tabs are illegal in YAML. This is the single most common breakage.
const tabbed = wfLines.filter((l) => l.includes(String.fromCharCode(9)));
console.log("lines containing a TAB:", tabbed.length, tabbed.length ? "<- would fail" : "<- good");

// 2. The keys a workflow cannot do without.
for (const key of ["name:", "on:", "jobs:", "runs-on:", "steps:"]) {
  console.log(`  ${wf.includes(key) ? "present" : "MISSING"}  ${key}`);
}

// 3. Which branch does it actually trigger on?
const branch = wfLines.find((l) => l.includes("branches:"));
console.log("trigger branch line:", branch?.trim());

// Find every path those workflows reference, and check whether it exists.
import { REPO_ROOT } from "../_shared/deno-helpers.ts";

const dir = `${REPO_ROOT}/.github/workflows`;
const referenced = new Set<string>();

for await (const entry of Deno.readDir(dir)) {
  const text = await Deno.readTextFile(`${dir}/${entry.name}`);
  for (const m of text.matchAll(/week\d[\w/.-]*\.(ts|mts|json|ipynb)/g)) referenced.add(m[0]);
}

let missing = 0;
for (const path of [...referenced].sort()) {
  const exists = await Deno.stat(`${REPO_ROOT}/${path}`).then(() => true).catch(() => false);
  if (!exists) missing++;
  console.log(`${exists ? "EXISTS " : "MISSING"}  ${path}`);
}
console.log(`\n${missing} of ${referenced.size} referenced files are gone.`);
